pub trait ZcashSerialize: Sized {
    /// Write `self` to the given `writer` using the canonical format.
    ///
    /// This function has a `zcash_` prefix to alert the reader that the
    /// serialization in use is consensus-critical serialization, rather than
    /// some other kind of serialization.
    ///
    /// This function is infallible except for errors in the underlying writer,
    /// so it can be used in contexts (such as hashing) where the serialized
    /// bytes must always be available.
    fn zcash_serialize<W: io::Write>(&self, writer: W) -> Result<(), io::Error>;
