### Design: connection state machine

```rust
use std::sync::Arc;

use futures::{
    channel::{mpsc, oneshot},
    future::{self, Either},
    prelude::*,
    stream::Stream,
};
use tokio::time::{delay_for, Delay};
use tower::Service;

use zebra_chain::block::{Block, BlockHeaderHash};
use zebra_chain::{serialization::SerializationError, transaction::TransactionHash};

use crate::{
    constants,
    protocol::{
        external::{InventoryHash, Message},
        internal::{Request, Response},
    },
    BoxedStdError,
};

use super::{ClientRequest, ErrorSlot, PeerError, SharedPeerError};

/// The state of a peer connection.
#[derive(Debug)]
pub(super) enum State {
    /// Awaiting a client request or a peer message.
    AwaitingRequest,
    /// Awaiting a peer message which we can interpret as a response to a pending client request.
    AwaitingResponse,
    /// A failure has occurred and we are shutting down the connection.
    Failed,
}

/// A pending client request.
///
/// Some requests have a response consisting of a single message, while
/// others require multiple messages to complete, so we track them
/// statefully.
#[derive(Debug)]
pub(super) enum PendingRequest {
    /// A request which expects a single message response.
    Single(Request, oneshot::Sender<Result<Response, SharedPeerError>>),
    /// A request which expects multiple block messages, one for each requested hash.
    BlocksByHash {
        /// The requested block hashes.
        block_requests: Vec<BlockHeaderHash>,
        /// The blocks received so far.
        blocks: Vec<Block>,
        /// The response channel.
        tx: oneshot::Sender<Result<Response, SharedPeerError>>,
    },
}

/// The "connection" duplex half of a peer connection.
#[derive(Debug)]
pub struct Connection<S, Tx> {
    pub(super) state: State,
    pub(super) pending_request: Option<PendingRequest>,
    request_timer: Option<Delay>,
    pub(super) svc: S,
    pub(super) client_rx: mpsc::Receiver<ClientRequest>,
    pub(super) error_slot: ErrorSlot,
    pub(super) peer_tx: Tx,
}
```

