use std::{
    marker::PhantomData,
    pin::Pin,
    task::{Context, Poll},
};

use futures::future::BoxFuture;
use tower::{Layer, Service};

/// Requests that can be retried.
#[derive(Copy, Clone, Debug)]
pub enum RetryLimit {
    /// Retry this request indefinitely.
    Unlimited,
    /// Retry this request, up to a maximum number of times.
    Count(usize),
}

impl RetryLimit {
    /// Returns true if the retry limit is unlimited.
    fn is_unlimited(&self) -> bool {
        matches!(self, RetryLimit::Unlimited)
    }
}

/// A boxed tower Service for requests and responses.
type BoxService<T, U> = Box<
    dyn Service<
            T,
            Response = U,
            Error = BoxedStdError,
            Future = BoxFuture<'static, Result<U, BoxedStdError>>,
        > + Send,
>;

/// A [`tower::retry::Policy`].  This type is `Clone` because the retry policy
/// must be cloned for each retry attempt.
#[derive(Clone, Debug)]
pub struct Retry<Req> {
    remaining_retries: usize,
    unlimited: bool,
    _service: PhantomData<Req>,
}

impl<Req> Retry<Req> {
    /// Create a new [`Retry`] policy.
    pub fn new(attempts: RetryLimit) -> Self {
        Self {
            // this is max retries, so we set unlimited to true if unlimited
            remaining_retries: match attempts {
                RetryLimit::Unlimited => usize::MAX,
                RetryLimit::Count(n) => n,
            },
            unlimited: attempts.is_unlimited(),
            _service: PhantomData,
        }
    }
}

impl<Req> tower::retry::Policy<Req, Response, BoxedStdError> for Retry<Req>
where
    Req: Clone,
{
    // Retry on any error.
    type Future = future::Ready<()>;

    fn retry(&mut self, _req: &Req, result: Result<&Response, &BoxedStdError>) -> Option<Self::Future> {
        if self.unlimited {
            Some(future::Ready(()))
        } else {
            match result {
                Err(_) if self.remaining_retries > 0 => {
                    self.remaining_retries -= 1;
                    Some(future::Ready(()))
                }
                Err(_) => None,
                Ok(_) => None,
            }
        }
    }

    fn clone_request(&mut self, req: &Req) -> Option<Req> {
        Some(req.clone())
    }
}

