//! Retry policies for outbound network requests.
//!
//! This module defines a simple retry policy which can be applied to a
//! [`tower::Service`] handle to the network, so that requests which fail due to
//! transient errors are automatically retried.

use std::{fmt::Debug, marker::PhantomData};

use futures::future::{self, Ready};
use tower::{retry::Policy, Layer, Service};

use crate::{BoxedStdError, Request, Response};

/// The number of times a request should be retried after a failure.
#[derive(Copy, Clone, Debug, Eq, PartialEq)]
pub enum RetryLimit {
    /// Retry requests indefinitely.
    Unlimited,
    /// Retry requests, up to `n` retries after the initial attempt.
    Count(usize),
}

impl Default for RetryLimit {
    fn default() -> RetryLimit {
        RetryLimit::Count(3)
    }
}

/// A [`tower::retry::Policy`] which retries requests that fail, up to a
/// configurable number of retries.
///
/// Each new policy is constructed from the previous one, decrementing the
/// number of remaining retries, so that a request is retried at most the
/// configured number of times before its failure is returned to the caller.
#[derive(Clone, Debug)]
pub struct Retry<Req> {
    /// The number of retries which have not yet been used.
    retry_limit: RetryLimit,
    /// The type of the request, which is phantom because the policy does not
    /// actually inspect requests.
    _service: PhantomData<Req>,
}

impl<Req> Retry<Req> {
    /// Construct a new retry policy with the given `retry_limit`.
    pub fn new(retry_limit: RetryLimit) -> Self {
        Retry {
            retry_limit,
            _service: PhantomData,
        }
    }
}

impl<Req> Policy<Req, Response, BoxedStdError> for Retry<Req>
where
    Req: Clone,
{
    type Future = Ready<Self>;

    fn retry(
        &self,
        _req: &Req,
        result: Result<&Response, &BoxedStdError>,
    ) -> Option<Self::Future> {
        match result {
            // Do not retry successful responses.
            Ok(_) => None,
            // Retry failed requests according to the retry limit.
            Err(_) => match self.retry_limit {
                RetryLimit::Unlimited => Some(future::ready(self.clone())),
                RetryLimit::Count(0) => None,
                RetryLimit::Count(n) => {
                    Some(future::ready(Retry::new(RetryLimit::Count(n - 1))))
                }
            },
        }
    }

    fn clone_request(&self, req: &Req) -> Option<Req> {
        Some(req.clone())
    }
}

/// Wraps a [`Service`] in an inner retry policy.
///
/// This can be used to apply a [`Retry`] retry policy to any [`Service`]
/// handling zebra-network [`Request`]s.
#[derive(Clone, Debug)]
pub struct RetryLayer {
    /// The retry limit applied to requests.
    retry_limit: RetryLimit,
}

impl RetryLayer {
    /// Construct a new retry layer with the given `retry_limit`.
    pub fn new(retry_limit: RetryLimit) -> Self {
        RetryLayer { retry_limit }
    }
}

impl<S> Layer<S> for RetryLayer {
    type Service = tower::retry::Retry<Retry<Request>, S>;

    fn layer(&self, service: S) -> Self::Service {
        tower::retry::Retry::new(Retry::new(self.retry_limit), service)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn get_error() -> BoxedStdError {
        Box::new(std::io::Error::new(std::io::ErrorKind::Other, "test error"))
    }

    #[test]
    fn retries_until_limit() {
        let req = Request::GetPeers;
        let error = get_error();

        // Retry limit of 2 means one retry after the initial attempt is allowed
        // for each error, for two total retries.
        let policy = Retry::new(RetryLimit::Count(2));
        let result: Result<&Response, &BoxedStdError> = Err(&error);
        let future = policy
            .retry(&req, result)
            .expect("request should be retried");
        let policy = futures::executor::block_on(future);
        assert_eq!(policy.retry_limit, RetryLimit::Count(1));

        let result: Result<&Response, &BoxedStdError> = Err(&error);
        let future = policy
            .retry(&req, result)
            .expect("request should be retried");
        let policy = futures::executor::block_on(future);
        assert_eq!(policy.retry_limit, RetryLimit::Count(0));

        let result: Result<&Response, &BoxedStdError> = Err(&error);
        assert!(
            policy.retry(&req, result).is_none(),
            "request should not be retried after the retry limit is exhausted"
        );
    }

    #[test]
    fn does_not_retry_successful_responses() {
        let req = Request::GetPeers;
        let policy = Retry::new(RetryLimit::Count(2));
        let result: Result<&Response, &BoxedStdError> = Ok(&Response::Ok);
        assert!(
            policy.retry(&req, result).is_none(),
            "successful responses should not be retried"
        );
    }

    #[test]
    fn unlimited_retries() {
        let req = Request::GetPeers;
        let policy = Retry::new(RetryLimit::Unlimited);
        let error = get_error();

        for _ in 0..10 {
            let result: Result<&Response, &BoxedStdError> = Err(&error);
            let future = policy
                .retry(&req, result)
                .expect("request should be retried");
            let policy_after = futures::executor::block_on(future);
            assert_eq!(policy_after.retry_limit, RetryLimit::Unlimited);
        }
    }
}

