//! Memo (plaintext) types.

use std::convert::TryFrom;
use std::fmt;
use std::str;

/// A memo (a plaintext) field for a note.
///
/// The memo field is an optional 512-byte message attached to a [note][1].
///
/// Zebra does not currently check that the memo field is valid UTF-8, so the
/// memo field may contain arbitrary data rather than text.
///
/// The memo is a plaintext type: the parent note (and thus the memo) is
/// encrypted before being committed to the chain.
///
/// [1]: https://zips.z.cash/protocol/protocol.pdf#notept
#[derive(Clone, Eq, PartialEq)]
pub struct Memo(Box<[u8; 512]>);

impl Memo {
    /// The maximum size allowed for a memo field, in bytes.
    pub const MAX_LENGTH: usize = 512;
}

impl<'a> TryFrom<&'a [u8]> for Memo {
    type Error = MemoError;

    fn try_from(memo_data: &'a [u8]) -> Result<Self, Self::Error> {
        // We use 512 bytes here, which is the "a note transmitted with the
        // transaction" size described in the Zcash protocol specification.
        let mut memo_bytes = Box::new([0; 512]);
        memo_bytes[0..memo_data.len().min(512)].copy_from_slice(&memo_data[..512.min(memo_data.len())]);
        Ok(Memo(memo_bytes))
    }
}

impl fmt::Debug for Memo {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        let memo = self.0;
        let memo_s = if let Ok(s) = str::from_utf8(&memo[..]) {
            s.to_owned()
        } else {
            hex::encode(&memo[..])
        };
        f.debug_tuple("Memo").field(&memo_s).finish()
    }
}

/// An error indicating that the memo field is invalid.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum MemoError {
    /// The memo data was too long to be contained in a 512-byte memo field.
    MemoTooLong,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn memo_try_from_str_ok() {
        let memo = Memo::try_from("test memo").unwrap();

        let mut expected = [0u8; 512];
        expected[..9].copy_from_slice(&b"test memo"[..]);

        assert_eq!(&memo.0[..], &expected[..]);
    }

    #[test]
    fn memo_try_from_long_err() {
        let memo = Memo::try_from(&[0u8; 513][..]).unwrap_err();

        assert_eq!(memo, MemoError::MemoTooLong);
    }

    #[test]
    fn memo_debug_utf8() {
        let memo = Memo::try_from("a".repeat(512).as_bytes()).unwrap();
        assert_eq!(format!("{:?}", memo), format!("Memo(\"{}\")", "a".repeat(512)));
    }

    #[test]
    fn memo_debug_non_utf8() {
        let memo = Memo::try_from(&[0xff; 512][..]).unwrap();
        let memo_debug = format!("{:?}", memo);

        assert!(memo_debug.contains("ff"));
    }
}

