```rust
/// The type of event that the crawler reacts to.
///
/// Connection attempts are triggered periodically or on demand from the peer
/// set, and failed attempts are reported back to the candidate set so that
/// their addresses can be retried later.
enum ConnectSignal {
    /// A demand for more connections (either periodic or from the peer set).
    Connect,
    /// A connection attempt to a candidate failed.
    Failed(MetaAddr),
}

/// Connect to `candidate` using `connector`, sending the resulting
/// [`Change`] to the peer set on success, or reporting the failure to the
/// crawler on error. This is run as an independent task, so that multiple
/// connection attempts can be in flight at the same time.
#[instrument(skip(connector, success_tx, failed_tx))]
async fn connect_and_report<C>(
    connector: C,
    candidate: MetaAddr,
    mut success_tx: mpsc::Sender<PeerChange>,
    mut failed_tx: mpsc::Sender<MetaAddr>,
) where
    C: Service<SocketAddr, Response = Change<SocketAddr, peer::Client>, Error = BoxedStdError>
        + Clone,
    C::Future: Send + 'static,
{
    // A failed readiness check (e.g., a timeout) is effectively a failed
    // connection attempt, so report it to the candidate set too.
    let mut connector = match connector.ready().await {
        Ok(connector) => connector,
        Err(e) => {
            debug!(%e, ?candidate.addr, "failed to get a connector: marking candidate as failed");
            let _ = failed_tx.send(candidate).await;
            return;
        }
    };

    match connector.call(candidate.addr).await {
        Ok(change) => {
            debug!("Successfully dialed new peer, sending to peerset");
            let _ = success_tx.send(Ok(change)).await;
        }
        Err(e) => {
            debug!(%e, ?candidate.addr, "marking address as failed");
            let _ = failed_tx.send(candidate).await;
        }
    }
}

