async fn crawl_and_dial<C, S>(
    new_peer_interval: Duration,
    demand_signal: mpsc::Receiver<()>,
    mut candidates: CandidateSet<S>,
    connector: C,
    mut success_tx: mpsc::Sender<PeerChange>,
) -> Result<(), BoxedStdError>
where
