        + Clone,
    C::Future: Send + 'static,
    S: Service<Request, Response = Response, Error = BoxedStdError>,
    S::Future: Send + 'static,
{
    // Handshake futures are spawned as independent tasks, so that multiple
    // connection attempts can proceed concurrently without blocking the
    // peer management loop. Use a channel to report failed attempts back to
    // the candidate set.
    const FAILURE_REPORT_BUFFER_SIZE: usize = 100;
    const MAX_CANDIDATE_BATCH_SIZE: usize = 50;

