                        None => {
                            // Refresh the candidate set, then try again. If
                            // there really are no candidates, wait for the
                            // next connection trigger.
                            candidates.update().await?;
                            match candidates.next() {
                                Some(candidate) => candidate,
                                None => {
                                    warn!("got demand for more peers but no available candidates");
                                    break;
                                }
                            }
                        }
                    };

                    tokio::spawn(connect_and_report(
                        connector.clone(),
                        candidate,
                        success_tx.clone(),
                        failed_tx.clone(),
                    ));

                    batch_size += 1;
                    if batch_size >= MAX_CANDIDATE_BATCH_SIZE {
                        break;
                    }
                }
            }
        }
    }

    Ok(())
}

/// The events that the crawler reacts to.
///
/// Connection attempts are triggered periodically or on demand from the peer
/// set, and failed attempts are reported back to the candidate set so their
/// addresses can be retried later.
enum ConnectSignal {
    /// A demand for more connections, either periodic or from the peer set.
    Connect,
    /// A connection attempt to a candidate failed.
    Failed(MetaAddr),
}

/// Connect to `candidate` using `connector`, sending the resulting
/// [`Change`] to the peer set on success, or reporting the failure to the
/// crawler on error.
///
/// This is spawned as an independent task, so that multiple connection
/// attempts can proceed concurrently without blocking the peer management
/// loop.
#[instrument(skip(connector, success_tx, failed_tx))]
async fn connect_and_report<C>(
    connector: C,
    candidate: MetaAddr,
    mut success_tx: mpsc::Sender<PeerChange>,
    mut failed_tx: mpsc::Sender<MetaAddr>,
) where
    C: Service<SocketAddr, Response = Change<SocketAddr, peer::Client>, Error = BoxedStdError>
        + Clone,
    C::Future: Send + 'static,
{
    // A failed readiness check (e.g., a timeout) is effectively a failed
    // connection attempt, so report the candidate as failed too.
    let mut connector = match connector.ready().await {
        Ok(connector) => connector,
        Err(e) => {
            debug!(%e, ?candidate.addr, "connector failed readiness check");
            let _ = failed_tx.send(candidate).await;
            return;
        }
    };

    match connector.call(candidate.addr).await {
        Ok(change) => {
            debug!("Successfully dialed new peer, sending to peerset");
            let _ = success_tx.send(Ok(change)).await;
        }
        Err(e) => {
            // Report failed connections with the MetaAddr, so they can be
            // retried by the CandidateSet later.
            debug!(%e, ?candidate.addr, "marking address as failed");
            let _ = failed_tx.send(candidate).await;
        }
    }
}

