//! `revhex` subcommand - reverse the byte order of a hex string.

use abscissa_core::{Command, Options, Runnable};

/// `revhex` subcommand
///
/// Zcash protocol tooling (such as `zcash-cli` and block explorers) prints
/// hash digests in reverse byte order compared to Zebra's internal [`Debug`]
/// output, so it can be convenient to reverse a hash when comparing the two.
#[derive(Command, Debug, Options)]
pub struct RevhexCmd {
    /// The hex string whose byte order should be reversed.
    #[options(free, help = "The hex string to reverse the byte order of.")]
    hex: String,
}

impl Runnable for RevhexCmd {
    /// Reverse the byte order of the given hex string.
    fn run(&self) {
        match revhex(&self.hex) {
            Ok(reversed) => println!("{}", reversed),
            Err(e) => {
                eprintln!("error: {}", e);
                std::process::exit(1);
            }
        }
    }
}

/// Reverse the byte order of the bytes encoded in `hex_str`.
fn revhex(hex_str: &str) -> Result<String, hex::FromHexError> {
    let mut bytes = hex::decode(hex_str.trim())?;
    bytes.reverse();
    Ok(hex::encode(bytes))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn reverses_byte_order() {
        assert_eq!(revhex("0001020304").unwrap(), "0403020100");
        assert_eq!(revhex("aabbcc").unwrap(), "ccbbaa");
    }

    #[test]
    fn rejects_invalid_hex() {
        assert!(revhex("zz").is_err());
    }
}

